import { DerivedPhysicsConstants } from './types.js';

export function generateGodot4CharacterBody2D(physics: DerivedPhysicsConstants): string {
  return `extends CharacterBody2D
# ============================================================================
# Auto-generated by GEA (Game Engine & Mechanics Anything)
# Clean-Room Godot 4 Platformer Kinematics Controller
# ============================================================================

# Derived Physical Constants
const SPEED: float = ${physics.maxHorizontalSpeed}.0
const ACCELERATION: float = ${physics.acceleration}.0
const FRICTION: float = ${physics.friction}.0

const JUMP_VELOCITY: float = -${physics.initialJumpVelocity}.0
const BASE_GRAVITY: float = ${physics.gravity}.0
const FALL_MULTIPLIER: float = ${physics.fallMultiplier}
const LOW_JUMP_MULTIPLIER: float = ${physics.lowJumpMultiplier}

# Juice & Game Feel
const COYOTE_TIME: float = ${physics.coyoteTimeMs / 1000.0}
const JUMP_BUFFER: float = ${physics.jumpBufferMs / 1000.0}

var coyote_timer: float = 0.0
var jump_buffer_timer: float = 0.0

func _physics_process(delta: float) -> void:
	# Update timers
	if is_on_floor():
		coyote_timer = COYOTE_TIME
	else:
		coyote_timer -= delta

	if Input.is_action_just_pressed("ui_accept"):
		jump_buffer_timer = JUMP_BUFFER
	else:
		jump_buffer_timer -= delta

	# Gravity computation with fall and low jump multipliers
	if not is_on_floor():
		var current_gravity = BASE_GRAVITY
		if velocity.y > 0:
			current_gravity *= FALL_MULTIPLIER
		elif velocity.y < 0 and not Input.is_action_pressed("ui_accept"):
			current_gravity *= LOW_JUMP_MULTIPLIER
		velocity.y += current_gravity * delta

	# Jump trigger with coyote time & buffering
	if jump_buffer_timer > 0.0 and coyote_timer > 0.0:
		velocity.y = JUMP_VELOCITY
		jump_buffer_timer = 0.0
		coyote_timer = 0.0

	# Horizontal movement with acceleration & friction smoothing
	var direction := Input.get_axis("ui_left", "ui_right")
	if direction != 0:
		velocity.x = move_toward(velocity.x, direction * SPEED, ACCELERATION * delta)
	else:
		velocity.x = move_toward(velocity.x, 0.0, FRICTION * delta)

	move_and_slide()
`;
}
